#pragma once
#include "RuntimeArmIK.hpp"
#include <sstream>
#include <iomanip>
struct InteractionBox {
 DriverIK::V center{},half{.04f,.04f,.04f};DriverIK::Q rotation{1,0,0,0};float scale=1;DriverIK::V stretch{1,1,1};
};
// Contact selection follows the visible rotated and scaled box, without a hidden grab margin.
inline bool InteractionBoxContainsPoint(const InteractionBox& box,DriverIK::V position){auto local=DriverIK::Rotate(DriverIK::Inverse(box.rotation),DriverIK::Sub(position,box.center));for(unsigned axis=0;axis<3;++axis)if(!std::isfinite(local[axis])||std::abs(local[axis])>box.half[axis]*box.scale*box.stretch[axis])return false;return true;}
struct BoxGrabInput {DriverIK::V position{};DriverIK::Q rotation{1,0,0,0};bool valid=false;float grip=0;int rayBox=-1;float rayDistance=2;};
inline constexpr unsigned InteractionBoxCount=18;
inline constexpr const char* InteractionBoxNames[InteractionBoxCount]={"ignition","horn","mirror_left","mirror_center","mirror_right","seat","window_left","window_right","steering_wheel","lights","wipers","radio","hand_left","hand_right","dashboard","infotainment","foot_left","foot_right"};
struct InteractionBoxEditor {
 InteractionBox boxes[InteractionBoxCount]{{},{ {},{.06f,.05f,.05f},{1,0,0,0},1.25f },{{-.85f,1.2f,-.35f},{.07f,.07f,.05f}},{{-.15f,1.4f,-.5f},{.07f,.05f,.05f}},{{.65f,1.2f,-.35f},{.07f,.07f,.05f}},{{-.38f,.52f,-.08f},{.06f,.06f,.06f}},{{-.75f,.7f,.05f},{.06f,.06f,.06f}},{{.65f,.7f,.05f},{.06f,.06f,.06f}},{{-.38f,.65f,-.35f},{.06f,.06f,.06f}},{{-.48f,.7f,-.6f},{.04f,.04f,.04f}},{{-.48f,.8f,-.6f},{.04f,.04f,.04f}},{{.05f,.7f,-.5f},{.07f,.04f,.04f}},{{.07f,0,0},{.04f,.035f,.055f},{1,0,0,0},1,{1.25f,1.428571429f,.909090909f}},{{-.07f,-.02f,0},{.04f,.035f,.055f},{1,0,0,0},1,{1.25f,1.428571429f,.909090909f}},{{.1f,1.6f,-.40f},{.05f,.05f,.05f}},{{.1f,1.36f,-.40f},{.05f,.05f,.05f}},{{0,0,0},{.05f,.05f,.05f}},{{0,0,0},{.05f,.05f,.05f}}};bool authored[InteractionBoxCount]{},enabled=false,dirty=false;bool down[2]{true,true};int selected=-1,owner=-1;bool two=false;DriverIK::V localOffset{},startMid{},startVector{};DriverIK::Q localRotation{1,0,0,0};InteractionBox startBox{};unsigned resizeAxis=0;float startSpan=0;
 void Release(){if(selected>=0)dirty=true;selected=owner=-1;two=false;}
 int Toggle(){enabled=!enabled;Release();down[0]=down[1]=true;return enabled?1:2;}
 void Anchor(unsigned side,const BoxGrabInput& in){owner=side;two=false;localOffset=DriverIK::Rotate(DriverIK::Inverse(in.rotation),DriverIK::Sub(boxes[selected].center,in.position));localRotation=DriverIK::Product(DriverIK::Inverse(in.rotation),boxes[selected].rotation);}
 void Step(const BoxGrabInput (&in)[2],unsigned selectableCount=InteractionBoxCount,bool handsAvailable=true){
  bool held[2]{},edge[2]{};for(unsigned i=0;i<2;++i){held[i]=in[i].valid && in[i].grip>(down[i]?.3f:.65f);edge[i]=held[i]&&!down[i];if(!in[i].valid)down[i]=true;else if(in[i].grip<.3f)down[i]=false;else if(held[i])down[i]=true;}
  if(!enabled){Release();return;}
  if(selected<0){float nearest=1e9f;for(unsigned side=0;side<2;++side)if(edge[side])for(unsigned box=0;box<std::min(selectableCount,InteractionBoxCount);++box){if(!handsAvailable&&(box==12||box==13||box>=16))continue;auto local=DriverIK::Rotate(DriverIK::Inverse(boxes[box].rotation),DriverIK::Sub(in[side].position,boxes[box].center));bool isNear=InteractionBoxContainsPoint(boxes[box],in[side].position);float d=DriverIK::Length(local);if(isNear && d<nearest){nearest=d;selected=box;owner=side;}}if(selected<0){float distance=1e9f;for(unsigned side=0;side<2;++side){int box=in[side].rayBox;if(edge[side]&&box>=0&&static_cast<unsigned>(box)<std::min(selectableCount,InteractionBoxCount)&&(handsAvailable||(box!=12&&box!=13&&box<16))&&std::isfinite(in[side].rayDistance)&&in[side].rayDistance>=0&&in[side].rayDistance<distance){selected=box;owner=side;distance=in[side].rayDistance;}}}if(selected>=0)Anchor(owner,in[owner]);}
  if(selected<0)return;
  if(!held[0]&&!held[1]){Release();return;}
  if(held[0]&&held[1]){
   auto mid=DriverIK::Mul(DriverIK::Add(in[0].position,in[1].position),.5f);auto axis=DriverIK::Sub(in[1].position,in[0].position);float length=DriverIK::Length(axis);
   if(!two){if(length<.02f)return;two=true;startMid=mid;startVector=axis;startBox=boxes[selected];auto local=DriverIK::Rotate(DriverIK::Inverse(startBox.rotation),axis);resizeAxis=0;for(unsigned j=1;j<3;++j)if(std::abs(local[j])>std::abs(local[resizeAxis]))resizeAxis=j;startSpan=local[resizeAxis];}
   auto local=DriverIK::Rotate(DriverIK::Inverse(startBox.rotation),axis);float ratio=std::abs(local[resizeAxis]/startSpan);if(!std::isfinite(ratio))return;auto candidate=startBox;candidate.stretch[resizeAxis]=std::max(.01f,startBox.stretch[resizeAxis]*ratio);auto offset=DriverIK::Rotate(DriverIK::Inverse(startBox.rotation),DriverIK::Sub(startBox.center,startMid));offset[resizeAxis]*=ratio;candidate.center=DriverIK::Add(mid,DriverIK::Rotate(startBox.rotation,offset));if(!std::isfinite(candidate.stretch[resizeAxis]))return;for(float v:candidate.center)if(!std::isfinite(v))return;boxes[selected]=candidate;authored[selected]=true;return;
  }
  unsigned side=held[0]?0:1;if(two || owner!=static_cast<int>(side))Anchor(side,in[side]);boxes[selected].center=DriverIK::Add(in[side].position,DriverIK::Rotate(in[side].rotation,localOffset));boxes[selected].rotation=DriverIK::Product(in[side].rotation,localRotation);authored[selected]=true;
 }
};
inline std::string SerializeInteractionBoxes(const InteractionBoxEditor& editor){std::ostringstream out;out<<std::setprecision(9)<<"SPF_INTERACTION_BOXES 12\n";for(unsigned i=0;i<InteractionBoxCount;++i){out<<InteractionBoxNames[i];for(float v:editor.boxes[i].center)out<<' '<<v;for(float v:editor.boxes[i].rotation)out<<' '<<v;out<<' '<<editor.boxes[i].scale;for(float v:editor.boxes[i].stretch)out<<' '<<v;out<<'\n';}return out.str();}
inline bool ParseInteractionBoxes(const std::string& text,InteractionBoxEditor& editor){std::istringstream in(text);std::string tag;unsigned version=0;if(!(in>>tag>>version)||tag!="SPF_INTERACTION_BOXES"||(version<1 || version>12))return false;auto candidate=editor;if(version<12){InteractionBoxEditor defaults;for(unsigned i=version<10?12:version<11?14:16;i<InteractionBoxCount;++i){candidate.boxes[i]=defaults.boxes[i];candidate.authored[i]=false;}}bool seen[InteractionBoxCount]{};for(unsigned row=0;row<(version==12?InteractionBoxCount:version==11?16:version==10?14:version==9?12:version==8?11:version==7?10:version==6?9:version==5?8:version==4?6:version==3?5:2);++row){if(!(in>>tag))return false;int i=-1;for(unsigned k=0;k<InteractionBoxCount;++k)if(tag==InteractionBoxNames[k])i=k;if(i<0||seen[i])return false;seen[i]=true;auto& box=candidate.boxes[i];for(float& v:box.center)if(!(in>>v)||!std::isfinite(v))return false;float norm=0;for(float& v:box.rotation){if(!(in>>v)||!std::isfinite(v))return false;norm+=v*v;}if(norm<.81f||norm>1.21f)return false;for(float& v:box.rotation)v/=std::sqrt(norm);if(!(in>>box.scale)||!std::isfinite(box.scale)||box.scale<=0)return false;box.stretch={1,1,1};if(version>=2)for(float& v:box.stretch)if(!(in>>v)||!std::isfinite(v)||v<=0)return false;candidate.authored[i]=true;}if(in>>tag)return false;candidate.Release();candidate.dirty=false;editor=candidate;return true;}
